const PREFIX='qadawi-shell:'+self.registration.scope;
const CACHE=PREFIX+'v4';
const legacy=['qadawi-shell-v1','qadawi-shell-v2','qadawi-shell-v3','qadawi-shell-v4'];
const SHELL=['./','./index.html','./style.css','./renewal.css','./product.css','./workspace.js','./appearance.js','./fonts/cairo.ttf','./fonts/naskh.ttf','./app.js','./journal.js','./core.js','./prompts.js','./assistant.js','./presentation.js','./fonts/arabic-regular.woff2','./fonts/arabic-medium.woff2','./fonts/arabic-semibold.woff2','./manifest.webmanifest','./icon.svg','./favicon.svg','./app-icon-192.png','./app-icon-512.png','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE&&(k.startsWith(PREFIX)||legacy.includes(k))).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.search)return;const allowed=SHELL.map(p=>new URL(p,self.registration.scope).pathname);if(!allowed.includes(url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.open(CACHE).then(cache=>cache.match(event.request))))});
